/** ⇒ 'TOO_SHORT' | 'TOO_LONG' | 'OK' | 'NOT_A_STRING' */
function checkLength(password, min, max) {
  // Write your solution here
  return password.length < min ? 'TOO_SHORT' : password.length > max ? 'TOO_LONG' : 'OK';
}

